def calibrate():
 def residual(x):
  Rb=Rot.from_rotvec(x[:3]).as_matrix(); Rc=Rot.from_rotvec(x[3:6]).as_matrix(); p=x[6:9]; off=x[9:12]
  ans=[]
  for s,C in samples:
   F=fk(s[4:11]); pred=Rb@(F[:3,3]+F[:3,:3]@off)+p+np.array([0,0,s[3]])
   ans.extend((pred-s[26:29])*5)
   ans.extend(Rot.from_matrix((Rb@F[:3,:3]@Rc).T@C).as_rotvec())
  return ans
 x=np.zeros(12);x[2]=np.pi/2;x[6:9]=[2.6,-1.3,.7];x[11]=.2
 sol=least_squares(residual,x,max_nfev=2000)
 global Rb,Rc,pbase,off,base_ref
 Rb=Rot.from_rotvec(sol.x[:3]).as_matrix();Rc=Rot.from_rotvec(sol.x[3:6]).as_matrix();pbase=sol.x[6:9];off=sol.x[9:12];base_ref=state()[:4].copy()
 print('FIT',np.linalg.norm(sol.fun),'Rb',Rb,'Rc',Rc,'pbase',pbase,'off',off)
 np.savez(OUT/'calibration.npz',Rb=Rb,Rc=Rc,pbase=pbase,off=off,base_ref=base_ref)

def pose(q=None):
 s=state();q=s[4:11] if q is None else q;F=fk(q)
 return Rb@(F[:3,3]+F[:3,:3]@off)+pbase+np.array([0,0,s[3]]), Rb@F[:3,:3]@Rc

def ik(p,C=None,q0=None):
 q0=state()[4:11].copy() if q0 is None else q0
 C=camrot() if C is None else C
 def fun(q):
  pp,RR=pose(q)
  return np.r_[(pp-p)*5,Rot.from_matrix(RR.T@C).as_rotvec(),(q-q0)*.015]
 sol=least_squares(fun,q0,bounds=([-2.89,-1.76,-2.89,-3.06,-2.89,-.017,-2.89],[2.89,1.76,2.89,-.069,2.89,3.75,2.89]),max_nfev=300)
 pp,RR=pose(sol.x);err=np.linalg.norm(pp-p);ang=np.linalg.norm(Rot.from_matrix(RR.T@C).as_rotvec())
 if err>.012 or ang>.07: raise ValueError(('IK unreachable',p,pp,err,ang))
 return sol.x

def moveto(p,C=None,n=50,grip=None):
